    p.mu.Lock()
    state, exists := p.txnState[msg.TxnID]
    p.mu.Unlock()

    if !exists {
        return ErrUnknownTransaction
    }

    if state.Status != ParticipantTxn3PCPreCommitted {
        return ErrInvalidState
    }

    // Commit the transaction
    if err := p.commitTransaction(msg.TxnID); err != nil {
        return err
    }

    state.Status = ParticipantTxn3PCCommitted
    return nil
}

