    p.mu.Lock()
    state, exists := p.txnState[msg.TxnID]
    p.mu.Unlock()

    if !exists {
        return ErrUnknownTransaction
    }

    if state.Status != ParticipantTxn3PCPrepared {
        return ErrInvalidState
    }

    // Abort the transaction
    if err := p.abortTransaction(msg.TxnID); err != nil {
        return err
    }

    state.Status = ParticipantTxn3PCAborted
    return nil
}

