One of the key features of 3PC is the timeout mechanism. Let's implement it:

```go
// StartTimeout starts a timeout for a transaction
func (p *Participant3PC) StartTimeout(txnID string, timeout time.Duration) {
    go func() {
        time.Sleep(timeout)
        p.mu.Lock()
        state, exists := p.txnState[txnID]
        p.mu.Unlock()

        if !exists {
            return
        }

        switch state.Status {
        case ParticipantTxn3PCInit:
            // Abort
            p.handleAbort(Message{TxnID: txnID, Type: GlobalAbort})
        case ParticipantTxn3PCPrepared:
            // Abort
            p.handleAbort(Message{TxnID: txnID, Type: GlobalAbort})
        case ParticipantTxn3PCPreCommitted:
            // Commit
            p.handleCommit(Message{TxnID: txnID, Type: GlobalCommit})
        }
    }()
}
